import{_ as e,o as a,c as r,a3 as n}from"./chunks/framework.CDCjIvJ8.js";const g=JSON.parse('{"title":"Introduction","description":"","frontmatter":{},"headers":[],"relativePath":"guide/introduction.md","filePath":"guide/introduction.md","lastUpdated":1789296458000}'),i={name:"guide/introduction.md"};function o(s,t,d,l,h,c){return a(),r("div",null,[...t[0]||(t[0]=[n('<h1 id="introduction" tabindex="-1">Introduction <a class="header-anchor" href="#introduction" aria-label="Permalink to &quot;Introduction&quot;">​</a></h1><p>DraftForge is a platform for teaching and assessing Indian statutory legal drafting. Students write affidavits, employment agreements, rent agreements and legal notices; the platform scores them against a calibrated rubric, cites the precedent behind each finding, and tutors the student toward fixing the gaps without writing the draft for them.</p><h2 id="the-problem" tabindex="-1">The problem <a class="header-anchor" href="#the-problem" aria-label="Permalink to &quot;The problem&quot;">​</a></h2><p>Legal drafting is taught through repetition and correction, but correction does not scale. A cohort of eighty students submitting three drafts each is 240 documents to mark by hand, and the marking is:</p><ul><li><strong>Slow</strong>, so feedback arrives after the student has moved on.</li><li><strong>Inconsistent</strong>, because two examiners weight the same omission differently.</li><li><strong>Unevidenced</strong>, because &quot;this clause is weak&quot; does not tell a student which statute they failed to satisfy.</li></ul><p>The obvious fix — hand the draft to a language model — introduces worse problems. Model scores drift between runs on identical input, so a student can resubmit unchanged work and get a different mark. Models hallucinate statutory citations, confidently attributing a provision to the wrong Act. And a model asked for feedback will usually just rewrite the draft, removing exactly the work the exercise exists to make the student do.</p><h2 id="the-approach" tabindex="-1">The approach <a class="header-anchor" href="#the-approach" aria-label="Permalink to &quot;The approach&quot;">​</a></h2><p>Grading is deterministic and generative assistance is separate.</p><h3 id="grading-runs-no-inference" tabindex="-1">Grading runs no inference <a class="header-anchor" href="#grading-runs-no-inference" aria-label="Permalink to &quot;Grading runs no inference&quot;">​</a></h3><p>The scorer is a rule engine. It classifies the document type, checks structural elements, matches mandatory clauses against an indexed reference corpus, applies formatting rules and subtracts gap penalties. Identical input produces an identical score, every time, and each point traces to a named criterion.</p><p>Vector search is used inside grading, but only to <em>locate evidence</em> — to find which passage of the student&#39;s draft corresponds to a required clause. The decision about whether that clause is adequate is rule-based.</p><h3 id="generation-is-confined-to-teaching" tabindex="-1">Generation is confined to teaching <a class="header-anchor" href="#generation-is-confined-to-teaching" aria-label="Permalink to &quot;Generation is confined to teaching&quot;">​</a></h3><p>The AI tutor, the drafting assistant and the evaluation explainer all use an LLM, and none of them can write to a score. The tutor is prompted to respond to &quot;what should this clause say?&quot; with a question about the governing statute rather than with the clause.</p><h3 id="evidence-is-citable" tabindex="-1">Evidence is citable <a class="header-anchor" href="#evidence-is-citable" aria-label="Permalink to &quot;Evidence is citable&quot;">​</a></h3><p>Every finding records where the reference came from: source document, section, page. A student disputing a mark is shown the rule, their text and the precedent, rather than an opaque number.</p><h2 id="who-uses-it" tabindex="-1">Who uses it <a class="header-anchor" href="#who-uses-it" aria-label="Permalink to &quot;Who uses it&quot;">​</a></h2><p><strong>Students</strong> draft in a versioned workspace, request evaluation, review findings with citations, work through a generated roadmap targeting their weak skills, and discuss their draft with the tutor.</p><p><strong>Instructors</strong> create classes, invite students by email, publish assignments, audit submissions side by side with diffs, override scores with a recorded reason, and read cohort-wide skill analytics.</p><p>Instructors are also the only route to an account: students do not self-register. See <a href="/DraftForge-2/flows/onboarding">Onboarding &amp; invitations</a>.</p><h2 id="technology" tabindex="-1">Technology <a class="header-anchor" href="#technology" aria-label="Permalink to &quot;Technology&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Layer</th><th style="text-align:left;">Choice</th></tr></thead><tbody><tr><td style="text-align:left;">API</td><td style="text-align:left;">FastAPI (Python 3.11+), Pydantic v2</td></tr><tr><td style="text-align:left;">Frontend</td><td style="text-align:left;">React 18, TypeScript, Vite, Tailwind</td></tr><tr><td style="text-align:left;">Relational store &amp; auth</td><td style="text-align:left;">Supabase PostgreSQL, Supabase Auth</td></tr><tr><td style="text-align:left;">Vector search</td><td style="text-align:left;">Qdrant Cloud</td></tr><tr><td style="text-align:left;">Knowledge graph</td><td style="text-align:left;">Neo4j Aura</td></tr><tr><td style="text-align:left;">Embeddings</td><td style="text-align:left;">FastEmbed ONNX (<code>BAAI/bge-small-en-v1.5</code>, 384-dim)</td></tr><tr><td style="text-align:left;">Inference</td><td style="text-align:left;">Groq Cloud, with local Ollama fallback</td></tr><tr><td style="text-align:left;">Rate limiting &amp; budgets</td><td style="text-align:left;">Redis</td></tr><tr><td style="text-align:left;">Email</td><td style="text-align:left;">Resend</td></tr><tr><td style="text-align:left;">Telemetry</td><td style="text-align:left;">OpenTelemetry → Grafana Cloud</td></tr><tr><td style="text-align:left;">Infrastructure</td><td style="text-align:left;">Terraform → Render, Cloudflare, Grafana Cloud</td></tr></tbody></table><p>Embeddings run locally rather than through an API. A 384-dimension ONNX model is small enough to run in-process, which removes a network hop from the retrieval path and means no draft text is sent to a third party for embedding.</p><h2 id="where-to-go-next" tabindex="-1">Where to go next <a class="header-anchor" href="#where-to-go-next" aria-label="Permalink to &quot;Where to go next&quot;">​</a></h2><ul><li><a href="/DraftForge-2/guide/quickstart">Quickstart</a> — get it running.</li><li><a href="/DraftForge-2/architecture/overview">System overview</a> — how the pieces fit.</li><li><a href="/DraftForge-2/flows/overview">Flows</a> — follow a request end to end.</li><li><a href="/DraftForge-2/security/model">Security model</a> — trust boundaries and how they are enforced.</li></ul>',24)])])}const f=e(i,[["render",o]]);export{g as __pageData,f as default};
